  const k = button.dataset.key;
  const down = e => { e.preventDefault(); if (k === 'space') jumpQueued = true; else { keys.add(k); if (k === 'w') jumpQueued = true; } };
  const up = e => { e.preventDefault(); if (k !== 'space') keys.delete(k); };
